INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT143-S4-Q3$batch08$, 143, 4, 3, $batch08$Most Strongly Supported$batch08$, $batch08$Cable TV stations have advantages that enable them to attract many more advertisers than broadcast networks attract. For example, cable stations are able to target particular audiences with 24-hour news, sports, or movies, whereas broadcast networks must offer a variety of programming. Cable can also offer lower advertising rates than any broadcast network can, because it is subsidized by viewers through subscriber fees. Additionally, many cable stations have expanded worldwide with multinational programming.$batch08$, $batch08$The statements above, if true, provide support for each of the following except:$batch08$, $batch08$A$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=143 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Some broadcast networks can be viewed in several countries.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Broadcast networks do not rely on subscriber fees from viewers.$batch08$, $batch08$Supported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Low costs are often an important factor for advertisers in selecting a station or network on which to run a TV ad.$batch08$, $batch08$Supported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Some advertisers prefer to have the opportunity to address a worldwide audience.$batch08$, $batch08$Supported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$The audiences that some advertisers prefer to target watch 24-hour news stations.$batch08$, $batch08$Supported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Cable stations attract more advertisers than broadcast networks because they can target audiences with 24-hour news, sports, or movies; they offer lower rates thanks to subscriber fees; and many have expanded worldwide.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$This is an EXCEPT question, so four answers are supported and one isn't. Each cable advantage implies something. Targeting helps only if some advertisers want those audiences. Lower rates help only if price matters. Worldwide reach helps only if some advertisers want it. And subscriber fees are something cable has that broadcast doesn't.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Find the one claim none of the advantages supports.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Worldwide expansion is listed as a *cable* advantage. Nothing supports broadcast networks reaching several countries. If anything, the contrast suggests they don't.$batch08$), ($batch08$B$batch08$, $batch08$Subscriber fees are what let cable charge less than "any broadcast network". That implies broadcast networks don't have them.$batch08$), ($batch08$C$batch08$, $batch08$Lower rates count as an advantage for attracting advertisers, so cost matters to advertisers.$batch08$), ($batch08$D$batch08$, $batch08$Worldwide expansion counts as an advantage, so some advertisers must want a worldwide audience.$batch08$), ($batch08$E$batch08$, $batch08$Targeting through 24-hour news is an advantage, so some advertisers want those audiences.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT143-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
